////////////////\n  // \u5b8c\u4e86\n\n  SerialUSB.println("### \u5b8c\u4e86.");\n}\n\nvoid loop()\n{\n  uint8_t val;\n  Rtc.EepromRead(0, &val, sizeof(val));\n  SerialUSB.print("EEPROM\u306e\u5024\u306f ");\n  SerialUSB.println(val);\n  \n  val++;\n  Rtc.EepromWrite(0, &val, sizeof(val));\n  \n  SerialUSB.println("\u30d3\u30fc\u30d7\u97f3.");\n  pinMode(WIO_D38, OUTPUT);\n  digitalWrite(WIO_D38, HIGH);\n  delay(200);\n  digitalWrite(WIO_D38, LOW);\n  \n  SerialUSB.println("\u30b7\u30e3\u30c3\u30c8\u30c0\u30a6\u30f3.");\n  Rtc.SetWakeupPeriod(BOOT_INTERVAL);\n  Rtc.Shutdown();\n  while (1) {}\n}\n')),(0,a.yg)("h2",{id:"\u56de\u8def\u56f3\u30aa\u30f3\u30e9\u30a4\u30f3\u30d3\u30e5\u30fc\u30a2"},"\u56de\u8def\u56f3\u30aa\u30f3\u30e9\u30a4\u30f3\u30d3\u30e5\u30fc\u30a2"),(0,a.yg)("div",{className:"altium-ecad-viewer","data-project-src":"https://files.seeedstudio.com/wiki/Wio_Extension-RTC/res/Wio%20Extension%20%E2%80%93%20RTC%20v1.0.zip",style:{borderRadius:"0px 0px 4px 4px",height:500,borderStyle:"solid",borderWidth:1,borderColor:"rgb(241, 241, 241)",overflow:"hidden",maxWidth:1280,maxHeight:700,boxSizing:"border-box"}}),(0,a.yg)("h2",{id:"\u30ea\u30bd\u30fc\u30b9"},"\u30ea\u30bd\u30fc\u30b9"),(0,a.yg)("ul",null,(0,a.yg)("li",{parentName:"ul"},(0,a.yg)("strong",{parentName:"li"},"[ZIP]")," ",(0,a.yg)("a",{parentName:"li",href:"https://files.seeedstudio.com/wiki/Wio_Extension-RTC/res/Wio%20Extension%20%E2%80%93%20RTC%20v1.0.zip"},"Wio-Extension-RTC")),(0,a.yg)("li",{parentName:"ul"},(0,a.yg)("strong",{parentName:"li"},"[\u30b5\u30f3\u30d7\u30eb]")," ",(0,a.yg)("a",{parentName:"li",href:"https://github.com/Seeed-Studio/Wio_Extension_RTC/blob/master/wiortc-sample.zip"},"Wio-Extension-RTC \u30b5\u30f3\u30d7\u30eb\u30b3\u30fc\u30c9"))),(0,a.yg)("h2",{id:"\u6280\u8853\u30b5\u30dd\u30fc\u30c8\u3068\u88fd\u54c1\u30c7\u30a3\u30b9\u30ab\u30c3\u30b7\u30e7\u30f3"},"\u6280\u8853\u30b5\u30dd\u30fc\u30c8\u3068\u88fd\u54c1\u30c7\u30a3\u30b9\u30ab\u30c3\u30b7\u30e7\u30f3"),(0,a.yg)("p"